-- Anonymous mutation generations detect changes to a fixed evidence set.
-- No answers, capabilities, participant snapshots or response IDs are copied.
CREATE TABLE reporting_generations (
 workspace_id TEXT PRIMARY KEY REFERENCES workspaces(id), generation INTEGER NOT NULL DEFAULT 0
);
INSERT INTO reporting_generations(workspace_id) SELECT id FROM workspaces;
CREATE TABLE reporting_changes (
 workspace_id TEXT NOT NULL REFERENCES workspaces(id), flow_id TEXT NOT NULL,
 eligible_at TEXT NOT NULL, generation INTEGER NOT NULL,
 PRIMARY KEY(workspace_id,flow_id,eligible_at)
);
CREATE INDEX reporting_changes_generation ON reporting_changes(workspace_id,flow_id,generation,eligible_at);
CREATE TRIGGER reporting_workspace_insert AFTER INSERT ON workspaces BEGIN
 INSERT INTO reporting_generations(workspace_id) VALUES(NEW.id);
END;
CREATE INDEX responses_reporting_page ON responses(workspace_id, flow_id, state, completed_at DESC, id DESC);
CREATE INDEX response_answers_reporting_question ON response_answers(step_id, response_id);
CREATE TRIGGER reporting_responses_insert AFTER INSERT ON responses BEGIN
 UPDATE reporting_generations SET generation = generation + 1 WHERE workspace_id IN (SELECT workspace_id FROM (SELECT NEW.workspace_id AS workspace_id,NEW.flow_id AS flow_id, CASE WHEN NEW.source = 'imported' THEN max(NEW.completed_at,NEW.released_at,t.committed_at) ELSE max(NEW.completed_at,NEW.released_at) END AS eligible_at FROM (SELECT 1) LEFT JOIN form_import_targets t ON t.target_id = NEW.id AND t.kind = 'response' AND t.workspace_id = NEW.workspace_id WHERE NEW.state = 'released' AND NEW.released_at IS NOT NULL AND (NEW.source != 'imported' OR t.committed_at IS NOT NULL)));
 INSERT INTO reporting_changes(workspace_id,flow_id,eligible_at,generation)
 SELECT changed.workspace_id,changed.flow_id,changed.eligible_at,g.generation FROM (SELECT NEW.workspace_id AS workspace_id,NEW.flow_id AS flow_id, CASE WHEN NEW.source = 'imported' THEN max(NEW.completed_at,NEW.released_at,t.committed_at) ELSE max(NEW.completed_at,NEW.released_at) END AS eligible_at FROM (SELECT 1) LEFT JOIN form_import_targets t ON t.target_id = NEW.id AND t.kind = 'response' AND t.workspace_id = NEW.workspace_id WHERE NEW.state = 'released' AND NEW.released_at IS NOT NULL AND (NEW.source != 'imported' OR t.committed_at IS NOT NULL)) changed
 JOIN reporting_generations g ON g.workspace_id = changed.workspace_id WHERE changed.eligible_at IS NOT NULL
 ON CONFLICT(workspace_id,flow_id,eligible_at) DO UPDATE SET generation = excluded.generation;
END;
